style.css:
@-moz-document domain("youtube.com") {
/* Fondo blanco */
html,
body,
ytd-app {
    background: #ffffff !important;
}

/* Elimina bordes redondeados */
* {
    border-radius: 0px !important;
}

/* Barra superior */
#masthead-container,
ytd-masthead {
    background: #ffffff !important;
    border-bottom: 1px solid #d3d3d3 !important;
    box-shadow: none !important;
}

/* Botón rojo clásico */
#logo-icon {
    color: #cc181e !important;
}

/* Barra lateral */
tp-yt-app-drawer,
#guide-content {
    background: #f5f5f5 !important;
}

/* Tarjetas */
ytd-rich-item-renderer,
ytd-video-renderer,
ytd-grid-video-renderer,
ytd-compact-video-renderer {
    background: white !important;
    border: 1px solid #ddd !important;
    padding: 6px !important;
    margin-bottom: 10px !important;
    box-shadow: none !important;
}

/* Miniaturas pequeñas */
ytd-thumbnail img,
ytd-thumbnail {
    border-radius: 0 !important;
}

/* Oculta Shorts */
ytd-rich-section-renderer,
ytd-reel-shelf-renderer,
ytd-shorts,
ytd-rich-shelf-renderer {
    display: none !important;
}

/* Oculta botón Crear */
ytd-topbar-menu-button-renderer {
    display: none !important;
}

/* Oculta "Gracias", "Clip", etc */
ytd-menu-renderer #top-level-buttons-computed {
    display: none !important;
}

/* Títulos */
#video-title {
    font-size: 15px !important;
    font-weight: bold !important;
    color: #167ac6 !important;
}

/* Texto */
#metadata-line,
#channel-name,
#owner-name {
    color: #666 !important;
    font-size: 12px !important;
}

/* Barra de búsqueda */
input#search {
    border: 1px solid #ccc !important;
    border-radius: 0 !important;
    background: white !important;
}

/* Botón Buscar */
#search-icon-legacy {
    border-radius: 0 !important;
    background: linear-gradient(#f8f8f8,#e0e0e0) !important;
    border: 1px solid #ccc !important;
}

/* Página del video */
ytd-watch-flexy {
    background: white !important;
}

/* Descripción */
#description {
    border: 1px solid #ddd !important;
    padding: 10px !important;
}

/* Comentarios */
ytd-comments {
    border-top: 1px solid #ddd !important;
}

/* Quitar degradados modernos */
yt-icon-button,
button {
    box-shadow: none !important;
}

/* Tipografía clásica */
body,
* {
    font-family: Arial, Helvetica, sans-serif !important;
}

/* Miniaturas estilo antiguo */
ytd-thumbnail img {
    border: 1px solid #bbb !important;
}

/* Hover azul */
a:hover {
    color: #167ac6 !important;
}

/* Oculta chips modernos */
ytd-feed-filter-chip-bar-renderer {
    display: none !important;
}

/* Oculta categorías */
ytd-chip-cloud-renderer {
    display: none !important;
}

/* Oculta paneles modernos */
ytd-mini-guide-renderer {
    display: none !important;
}

/* Hace la página un poco más estrecha */
#page-manager {
    max-width: 1250px !important;
    margin: auto !important;
}
}
